  "sql": "WITH _base AS (\n  SELECT\n    customers__regions.name AS \"orders.customers.regions.name\",\n    CAST(SUM(orders.amount) AS DOUBLE) AS \"orders.revenue\"\n  FROM orders AS orders\n  LEFT JOIN customers AS customers\n    ON orders.customer_id = customers.id\n  LEFT JOIN regions AS customers__regions\n    ON customers.region_id = customers__regions.id\n  GROUP BY\n    customers__regions.name\n), _cm_orders__customers__credit_sum AS (\n  SELECT\n    regions.name AS \"customers.regions.name\",\n    CAST(SUM(customers.credit) AS DOUBLE) AS \"customers.credit_sum\"\n  FROM customers AS customers\n  LEFT JOIN regions AS regions\n    ON customers.region_id = regions.id\n  GROUP BY\n    regions.name\n)\nSELECT\n  _base.\"orders.customers.regions.name\",\n  _base.\"orders.revenue\",\n  _cm_orders__customers__credit_sum.\"customers.credit_sum\" AS \"orders.credit\"\nFROM _base\nLEFT JOIN _cm_orders__customers__credit_sum\n  ON _base.\"orders.customers.regions.name\" IS NOT DISTINCT FROM _cm_orders__customers__credit_sum.\"customers.regions.name\"\nORDER BY\n  _base.\"orders.customers.regions.name\" ASC\nLIMIT 101"
}

